<?php
namespace Tests\Feature;use App\Models\Dashboard;use App\Models\DashboardWidget;use App\Models\Device;use App\Models\DeviceAccessAssignment;use App\Models\DeviceParameter;use App\Models\Notification;use App\Models\Organization;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CollaborationCommentsTest extends TestCase{use RefreshDatabase;private function user($o,$admin=false){return User::factory()->create(['organization_id'=>$o->id,'role'=>'staff','platform_role'=>$admin?'platform_admin':null,'status'=>'active']);}private function device($o,$n='D'){return Device::create(['organization_id'=>$o->id,'name'=>$n,'external_id'=>uniqid(),'type'=>'sensor','protocol'=>'mqtt']);}private function assign($u,$d,$l='viewer'){DeviceAccessAssignment::create(['user_id'=>$u->id,'device_id'=>$d->id,'access_level'=>$l]);}
public function test_viewer_can_create_reply_and_acknowledge_without_gaining_edit_access(){ $o=Organization::create(['name'=>'O','slug'=>'o']);$v=$this->user($o);$d=$this->device($o);$this->assign($v,$d);$res=$this->actingAs($v)->postJson("/api/collaboration/device/{$d->id}/threads",['body'=>'<script>alert(1)</script>'])->assertCreated()->assertJsonPath('status','open');$id=$res->json('id');$this->actingAs($v)->postJson("/api/collaboration/threads/$id/comments",['body'=>'reply'])->assertCreated();$this->actingAs($v)->postJson("/api/collaboration/threads/$id/acknowledge")->assertOk();$this->assertDatabaseHas('comment_acknowledgments',['thread_id'=>$id,'user_id'=>$v->id]);$this->assertDatabaseHas('collaboration_threads',['id'=>$id,'status'=>'open']);$this->actingAs($v)->patchJson("/api/devices/{$d->id}",['name'=>'no'])->assertForbidden();}
public function test_anchor_registry_accepts_owned_parameter_and_widget_and_rejects_foreign(){ $o=Organization::create(['name'=>'O','slug'=>'o']);$u=$this->user($o);$a=$this->device($o,'A');$b=$this->device($o,'B');$this->assign($u,$a);$p=DeviceParameter::create(['device_id'=>$a->id,'name'=>'P','key'=>'p','data_type'=>'number']);$foreign=DeviceParameter::create(['device_id'=>$b->id,'name'=>'Q','key'=>'q','data_type'=>'number']);$dash=Dashboard::create(['organization_id'=>$o->id,'device_id'=>$a->id,'name'=>'D','scope'=>'device']);$w=DashboardWidget::create(['id'=>'widget-1','dashboard_id'=>$dash->id,'widget_type'=>'value','title'=>'W','layout'=>[],'configuration'=>[],'position'=>0]);foreach([['parameter',(string)$p->id],['dashboard_widget',$w->id]] as [$type,$key])$this->actingAs($u)->postJson("/api/collaboration/device/{$a->id}/threads",['anchor_type'=>$type,'anchor_key'=>$key,'body'=>'ok'])->assertCreated();$this->actingAs($u)->postJson("/api/collaboration/device/{$a->id}/threads",['anchor_type'=>'parameter','anchor_key'=>(string)$foreign->id,'body'=>'no'])->assertUnprocessable();$this->actingAs($u)->postJson("/api/collaboration/device/{$a->id}/threads",['anchor_type'=>'css_selector','body'=>'no'])->assertUnprocessable();}
public function test_mentions_require_existing_access_and_emit_safe_notification_once(){ $a=Organization::create(['name'=>'A','slug'=>'a']);$b=Organization::create(['name'=>'B','slug'=>'b']);$actor=$this->user($a);$eligible=$this->user($a);$unassigned=$this->user($a);$foreign=$this->user($b);$d=$this->device($a);$this->assign($actor,$d);$this->assign($eligible,$d);$payload=['body'=>'hello','mention_ids'=>[$eligible->id,$eligible->id]];$this->actingAs($actor)->postJson("/api/collaboration/device/{$d->id}/threads",$payload)->assertUnprocessable();$payload['mention_ids']=[$eligible->id];$this->actingAs($actor)->postJson("/api/collaboration/device/{$d->id}/threads",$payload)->assertCreated();$this->assertDatabaseHas('notifications',['user_id'=>$eligible->id,'type'=>'comment.mentioned']);foreach([$unassigned,$foreign] as $bad)$this->actingAs($actor)->postJson("/api/collaboration/device/{$d->id}/threads",['body'=>'x','mention_ids'=>[$bad->id]])->assertUnprocessable();}
public function test_resolve_reopen_permissions_and_transition_history(){ $o=Organization::create(['name'=>'O','slug'=>'o']);$viewer=$this->user($o);$full=$this->user($o);$d=$this->device($o);$this->assign($viewer,$d);$this->assign($full,$d,'full_access');$id=$this->actingAs($viewer)->postJson("/api/collaboration/device/{$d->id}/threads",['body'=>'x'])->json('id');$this->actingAs($full)->postJson("/api/collaboration/threads/$id/resolve")->assertOk()->assertJsonPath('status','resolved');$this->actingAs($full)->postJson("/api/collaboration/threads/$id/reopen")->assertOk()->assertJsonPath('status','open');$this->assertDatabaseCount('collaboration_thread_transitions',2);$this->actingAs($viewer)->postJson("/api/collaboration/threads/$id/resolve")->assertOk();}
public function test_raw_ids_and_resource_types_reauthorize_after_access_revocation(){ $o=Organization::create(['name'=>'O','slug'=>'o']);$u=$this->user($o);$d=$this->device($o);$this->assign($u,$d);$id=$this->actingAs($u)->postJson("/api/collaboration/device/{$d->id}/threads",['body'=>'x'])->json('id');DeviceAccessAssignment::where('user_id',$u->id)->delete();$this->actingAs($u)->getJson("/api/collaboration/threads/$id")->assertNotFound();$this->actingAs($u)->postJson("/api/collaboration/threads/$id/comments",['body'=>'x'])->assertNotFound();$this->actingAs($u)->postJson("/api/collaboration/App%5CModels%5CDevice/{$d->id}/threads",['body'=>'x'])->assertUnprocessable();}}
